-- Driver for tests/test_lua_backend.py: runs the Lua Auto backend (identity, diagnosis, attest, platform, net,
-- recovery, deps, backend) on cases generated by Python and writes the outcomes for comparison with
-- native_switch.Linux and the Python modules it ports.
-- Usage: lua5.1 backend_differential.lua <cases.json> <results.json>
local here=(arg[0]:match('^(.*)/[^/]*$') or '.')
package.path=here..'/../../files/usr/lib/homensai-vpn/lua/?.lua;'..here..'/?.lua;'..package.path
-- sys.lua/runner.lua are never loaded here: every read goes through the fake router
package.preload['sys']=function() return {} end
local canon=require('canon')
canon.configure({runtime=os.getenv('HOMENSAI_TEST_RUNTIME') or '/tmp'})
local py=require('py')
local identity=require('identity')
local diagnosis=require('diagnosis')
local attest=require('attest')
local platform=require('platform')
local net=require('net')
local recovery=require('recovery')
local deps=require('deps')
local backend_mod=require('backend')
local fake=require('backend_fake')

local function read(path) local f=assert(io.open(path,'rb'));local s=f:read('*a');f:close();return s end
local function write(path,s) local f=assert(io.open(path,'wb'));f:write(s);f:close() end
local function unhex(h) return (string.gsub(h,'%x%x',function(x) return string.char(tonumber(x,16)) end)) end
local NULL=canon.null

local function outcome(fn,...)
  local ok,a,b=pcall(fn,...)
  if ok then
    if b~=nil then return canon.object({ok=canon.array({a==nil and NULL or a,b})}) end
    return canon.object({ok=a==nil and NULL or a})
  end
  if type(a)=='table' and type(a.code)=='string' then
    if a.value_error then return canon.object({value_error=a.code}) end
    return canon.object({refused=a.code})
  end
  return canon.object({error=tostring(a)})
end
local function none(v) if v==NULL then return nil end;return v end
local function lua_table(v)  -- canon list -> plain Lua list of strings (for sets of skip names)
  local out={};for i,x in ipairs(v) do out[i]=x end;return out
end

local function world_of(w)
  local world={files={},dirs={},ubus={},commands={},scripts={},chunks={},wall=canon.number(w.wall),clock=canon.number(w.clock or 1000),runtime=w.runtime}
  for k,v in pairs(w.files or {}) do world.files[k]=v end
  for k,v in pairs(w.hexfiles or {}) do world.files[k]=unhex(v) end
  for k,v in pairs(w.dirs or {}) do world.dirs[k]=lua_table(v) end
  for k,v in pairs(w.ubus or {}) do world.ubus[k]=v end
  for k,v in pairs(w.commands or {}) do world.commands[k]={rc=v.rc or 0,out=v.out or ''} end
  for k,v in pairs(w.scripts or {}) do world.scripts[k]=v end
  for k,v in pairs(w.chunks or {}) do world.chunks[k]=v end
  return world
end

local function backend_for(w)
  local world=world_of(w)
  local sys=fake.new(world)
  local B=backend_mod.new(sys)
  local env={run={wall=sys.wall,clock=sys.clock,lock=function(fn) return fn() end,fs={read=function(p) return world.files[p] end}},
    runtime=sys.RUNTIME,persist='/etc/homensai-vpn',stop=function() return false end,sleep=function() end}
  B.bind(env)
  env.backend=B
  if w.acceleration then local value=w.acceleration;B.acceleration=function() return py.copy(value) end end
  return B,sys,env
end

local H={}
function H.section_ids(c)
  local b=none(c.bindings)
  local ids={}
  for i,s in ipairs(c.sections) do ids[i]=identity.section_id(s,b) end
  local o=identity.policy_order(c.sections,b)
  return canon.object({ids=canon.array(ids),order=o,hash=identity.policy_hash(c.sections,b)})
end
function H.choose(c) return identity.choose(c.data,c.profiles) end
function H.resolve_pair(c)
  local r=diagnosis.resolve_pair(c.status,c.settings,c.now,c.max_age,c.settle)
  return canon.object({source=r.source,target=r.target,coordination=r.coordination})
end
function H.diagnose(c) return canon.object(diagnosis.diagnose(c.status,c.source,c.now,none(c.settings))) end
function H.scoped_samples(c) return diagnosis.scoped_samples(c.samples,c.profile) end
function H.attest(c) return attest.attest(c.policy,c.selection,c.mangle,c.rules) end
function H.missing_only(c) return attest.missing_only(c.policy,c.selection,c.mangle,c.rules) end
function H.static_bindings(c) return attest.static_bindings(c.selection,c.network) end
function H.unrouted(c) return attest.unrouted(c.text) end
function H.fingerprint(c)
  local chains=attest.parse(c.mangle)
  return canon.digest(canon.object({mangle=attest.as_value(chains),rules=c.rules}))
end
function H.normalized_network(c) return net.normalized_network(c.rows,none(c.managed)) end
function H.config_digest(c) return net.config_digest(c.name,unhex(c.data),none(c.managed)) end
function H.static_firewall_digest(c)
  local n=net.new({},{});return n.static_firewall_digest(unhex(c.data))
end
function H.settings_fingerprint(c) return identity.fingerprint(c.settings) end
function H.order_steps(c) return canon.array(recovery.order_steps(c.before,c.target)) end
function H.validate_step(c) return recovery.validate_step(c.journal) end
function H.order_allowed(c) return recovery.order_allowed(c.journal,c.order) end
function H.forward_proof(c) return recovery.forward_proof(c.journal) end
function H.restore_origin(c) return recovery.restore_origin(c.journal) end
function H.from_kernel(c) return deps.from_kernel(none(c.kernel),none(c.source),none(c.target),c.now) end
function H.zones(c)
  local set=platform.zones(c.text)
  local list={};for k in pairs(set) do list[#list+1]=k end;table.sort(list)
  return canon.array(list)
end
function H.hook_state(c) return platform.fresh_hook_state(c.lines,canon.number(c.after)) end
function H.appended(c) return platform.appended_hook_state(c.before,c.after) end
function H.selected_bindings(c) return identity.selected_bindings(c.sections,lua_table(c.interfaces)) end
function H.applied(c) return identity.applied(c.sections,none(c.bindings)) end
function H.roles(c) return identity.roles(c.settings) end
function H.valid_record(c) return deps.valid_record(c.record) end
function H.diagnostic(c)
  local B=backend_for(c.world)
  local saved=platform.assess
  local assess=c.world.assess
  platform.assess=function() return lua_table(assess) end
  local ok,blockers,selection=pcall(B.diagnostic)
  platform.assess=saved
  if not ok then error(blockers,0) end
  return canon.array(blockers),selection or NULL
end
function H.kernel_fingerprint(c)
  local B=backend_for(c.world)
  return B.kernel_fingerprint()
end
function H.attest_policy(c)
  local B=backend_for(c.world)
  local r=B.attest_policy(c.selection)
  r.time=nil
  return r
end
function H.order(c)
  local B=backend_for(c.world)
  if not py.isnone(c.bindings) then B.use_process_bindings(c.bindings) end
  local o,h=B.order()
  return canon.array({o,h})
end
function H.candidates(c) local B=backend_for(c.world);return B.candidates() end
function H.instant_request(c)
  local B=backend_for(c.world)
  if not py.isnone(c.bindings) then B.use_process_bindings(c.bindings) end
  local names,order=B.instant_request(nil,c.after)
  return canon.array({names,order})
end
function H.guard_script(c)
  local B,sys=backend_for(c.world)
  local installed=false
  sys.world.handler=function(argv)  -- nft: no table until `nft -f` ran
    if argv[1]~='nft' then return nil end
    if argv[2]=='list' then return installed and 0 or 1,installed and 'comment "homensai-owned-guard"' or '' end
    if argv[2]=='-c' then return 0,'' end
    if argv[2]=='-f' then installed=true;return 0,'' end
    return 1,''
  end
  B.guard(none(c.devices) and lua_table(c.devices) or nil)
  for _,w in ipairs(sys.writes) do if w[1]=='write' and string.find(w[2],'%.nft$') then return w[3] end end
  return NULL
end

local cases=canon.decode(read(arg[1]))
local results={}
for i,case in ipairs(cases) do
  local handler=H[case.kind]
  if not handler then results[i]=canon.object({error='no handler '..case.kind})
  else results[i]=outcome(handler,case.input) end
end
write(arg[2],canon.encode(canon.array(results)))
